from math12_reviewed_unit1 import heading,paragraph,page
from math12_reviewed_higher_derivatives import eq,note
from math12_native_geometry import geometry,path
FAMILY=geometry('Figure 7.22','Figure 7.22 — two intersecting lines L₁,L₂ and another member L₁+λL₂ = 0',[path([(225,300),(225,35)]),path([(45,240),(450,240)]),path([(120,60),(380,300)]),path([(50,260),(260,189.230769),(440,128.571429)]),path([(190,295.846154),(260,189.230769),(330,82.615385)])],[(223,25,'y'),(456,246,'x'),(197,263,'O'),(360,283,'A'),(380,306,'L₁'),(443,131,'L₂'),(335,65,'L₁+λL₂ = 0')])
TRIANGLE=geometry('Figure 7.23','Figure 7.23 — triangle ABC with interior angles θ₁,θ₂,θ₃',[path([(100,260),(430,260),(290,60),(100,260)])],[(81,277,'A'),(432,278,'B'),(285,45,'C'),(120,250,'θ₁'),(396,250,'θ₂'),(280,95,'θ₃')])
def example_triangle():
 def pt(x,y):return (80+(x+3)*44,300-(y+4)*30)
 paths=[path([pt(-3,0),pt(5,0)]),path([pt(0,-4),pt(0,5)]),path([pt(-2,-3),pt(4,-1),pt(2,3),pt(-2,-3)])]
 labels=[(*pt(5.2,0),'x'),(*pt(0,5.4),'y'),(pt(-2,-3)[0]-22,pt(-2,-3)[1]+17,'A'),(pt(4,-1)[0]+5,pt(4,-1)[1]+15,'B'),(pt(2,3)[0]+5,pt(2,3)[1]-8,'C'),(145,258,'θ₁'),(358,207,'θ₂'),(292,122,'θ₃')]
 for x in [-1,1,2,3,4]:
  v=pt(x,0);paths.append(path([(v[0],v[1]-4),(v[0],v[1]+4)]));labels.append((v[0]-4,v[1]+20,str(x)))
 for y in [-3,-2,-1,1,2,3,4]:
  v=pt(0,y);paths.append(path([(v[0]-4,v[1]),(v[0]+4,v[1])]));labels.append((v[0]+8,v[1]+5,str(y)))
 return geometry('Figure 7.24','Figure 7.24 — exact source vertices A(−2,−3), B(4,−1), C(2,3)',paths,labels,size=(500,370))
PAGES=[page('103_page_1.jpg',197,[heading('7.6.2 The equation of family of lines passing through the point of intersection of two given lines'),paragraph('Suppose, the two lines are'),eq(r'L_1:a_1x+b_1y+c_1=0','i'),eq(r'L_2:a_2x+b_2y+c_2=0','ii'),paragraph('and P(x₁,y₁) is their point of intersection. The given lines L₁ and L₂ are used to obtain a first degree equation of a straight line in x and y:'),eq(r'(a_1x+b_1y+c_1)+\lambda(a_2x+b_2y+c_2)=0,\quad\lambda\ \mathrm{is\ constant}','iii'),paragraph('The coordinates of a point P will reduce each line in (iii) to zero, since, by hypothesis, P is the point of intersection, i.e., it lies on each line. Therefore P satisfies (iii) and represents the family of lines through the point of intersection of L₁ = 0 and L₂ = 0.'),FAMILY,heading('Example 19'),paragraph('Develop the family of lines through the point of intersection of the lines 2x−3y+4 = 0 and 2x+y−1 = 0. Find the line from the family of lines which is (a) parallel to the line whose slope is m₁ = −2/3. (b) perpendicular to the line 4x+3y−1 = 0.'),heading('Solution'),paragraph('Result (iii) is used for the lines 2x−3y+4 = 0, 2x+y−1 = 0 to obtain the family of lines:'),eq(r'(2x-3y+4)+\lambda(2x+y-1)=0'),eq(r'(2+2\lambda)x+(-3+\lambda)y+(4-\lambda)=0','iv'),paragraph('The slope of the family of lines is:'),eq(r'(2+2\lambda)x+(-3+\lambda)y+(4-\lambda)=0\ \Rightarrow\ (-3+\lambda)y=-(2+2\lambda)x-(4-\lambda)'),eq(r'y=\frac{-(2+2\lambda)x}{-3+\lambda}-\frac{4-\lambda}{-3+\lambda},\quad m_2=\frac{-(2+2\lambda)}{-3+\lambda}'),paragraph('a. The family of lines (iv) is parallel to the line with slope m₁ = −2/3 if and only if their slopes are equal:'),eq(r'\frac{-(2+2\lambda)}{-3+\lambda}=-\frac23\ \Rightarrow\ 6+6\lambda=-6+2\lambda\ \Rightarrow\ 4\lambda=-12\ \Rightarrow\lambda=-3'),paragraph('The value of λ = −3 is used in (iv) to obtain the particular line from the family of lines (iv):'),eq(r'(2x-3y+4)-3(2x+y-1)=0\ \Rightarrow\ 2x-3y+4-6x-3y+3=0'),eq(r'\Rightarrow\ -4x-6y+7=0\ \Rightarrow\ 4x+6y-7=0'),paragraph('b. The slope of the given line 4x+3y−1 = 0 is m₃ = −4/3. The family of lines (iv) is perpendicular to the line 4x+3y−1 = 0, if and only if the product of their slopes equals −1:'),eq(r'\left[\frac{-(2+2\lambda)}{-3+\lambda}\right]\left(-\frac43\right)=-1\ \Rightarrow\ \frac{8+8\lambda}{-9+3\lambda}=-1\ \Rightarrow\ 8+8\lambda=9-3\lambda\ \Rightarrow\ 11\lambda=1\ \Rightarrow\lambda=\frac1{11}'),paragraph('The value of λ = 1/11 is used in (iv) to obtain the particular line from the family of lines:'),eq(r'(2x-3y+4)+\frac1{11}(2x+y-1)=0\ \Rightarrow\ 22x-33y+44+2x+y-1=0\ \Rightarrow\ 24x-32y+43=0'),note('For two distinct intersecting lines, every finite λ member passes through their intersection. This normalized expression omits L₂ itself; the complete pencil is αL₁+βL₂ = 0 with (α,β) ≠ (0,0). In this example λ = 3 gives a vertical line, so its slope quotient must not be used. The generic source figure is schematic; the actual example intersection is (−1/8,5/4).')]),page('103_page_2.jpg',198,[heading('7.6.3 The angles of the triangle when the slopes of the sides are given'),paragraph('If A(x₁,y₁), B(x₂,y₂) and C(x₃,y₃) are the vertices of a triangle ABC and the slopes of the sides AB, BC and CA of the triangle ABC are respectively:'),eq(r'm_1=\frac{y_2-y_1}{x_2-x_1},\quad\mathrm{slope\ of\ side}\ AB'),eq(r'm_2=\frac{y_3-y_2}{x_3-x_2},\quad\mathrm{slope\ of\ side}\ BC'),eq(r'm_3=\frac{y_1-y_3}{x_1-x_3},\quad\mathrm{slope\ of\ side}\ CA'),TRIANGLE,paragraph('If θ₁, θ₂ and θ₃ are the angles in between their sides AB to AC, BC to BA and CB to CA respectively, then the angles can be found through results tan θ = ±(m₁−m₂)/(1+m₁m₂). The angles from the sides AB to AC, BC to BA, and CA to CB of a triangle ABC are respectively:'),eq(r'\tan\theta_1=\frac{m_1-m_3}{1+m_1m_3},\quad\tan\theta_2=\frac{m_2-m_1}{1+m_1m_2},\quad\tan\theta_3=\frac{m_3-m_2}{1+m_2m_3}','v'),heading('Example 20'),paragraph('Find the angles of the triangle ABC, whose vertices are A(−2,−3), B(4,−1) and C(2,3).'),heading('Solution'),paragraph('If ABC is a triangle and the slopes of the sides AB, BC and CA are respectively:'),eq(r'm_1=\frac{y_2-y_1}{x_2-x_1}=\frac{-1+3}{4+2}=\frac26=\frac13,\quad\mathrm{slope\ of\ side}\ AB'),eq(r'm_2=\frac{y_3-y_2}{x_3-x_2}=\frac{3+1}{2-4}=\frac4{-2}=-2,\quad\mathrm{slope\ of\ side}\ BC'),eq(r'm_3=\frac{y_1-y_3}{x_1-x_3}=\frac{-3-3}{-2-2}=\frac{-6}{-4}=\frac32,\quad\mathrm{slope\ of\ side}\ CA'),example_triangle(),paragraph('Result (v) to obtain the angle θ₁ from the sides AB to AC use:'),eq(r'\tan\theta_1=\frac{m_1-m_3}{1+m_1m_3}=\frac{1/3-3/2}{1+(1/3)(3/2)}=\frac{2-9}{6(1+1/2)}=\frac{-7}{6(3/2)}=-\frac79\ \Rightarrow\theta_1=\tan^{-1}(-7/9)'),paragraph('Result (v) to obtain the angle θ₂ from the sides BC to BA use:'),eq(r'\tan\theta_2=\frac{m_2-m_1}{1+m_1m_2}=\frac{-2-1/3}{1+(-2)(1/3)}=\frac{-7/3}{1/3}=-7\ \Rightarrow\theta_2=\tan^{-1}(-7)'),paragraph('Result (v) to obtain the angle θ₃ from the sides CA to CB use:'),eq(r'\tan\theta_3=\frac{m_3-m_2}{1+m_2m_3}=\frac{3/2+2}{1+(-2)(3/2)}=\frac7{2(1-3)}=\frac7{-4}=-\frac74\ \Rightarrow\theta_3=\tan^{-1}(-7/4)'),note('The three displayed negative principal inverse tangents are not positive interior angles. Interior angles must be selected from the vertex rays, and an obtuse interior angle cannot always be replaced by the smaller angle between its infinite side-lines. Use the dot product of the two outward rays at each vertex, or atan2(|cross|,dot), which returns an interior angle between 0° and 180°. For this example all three ray dot products are positive, giving A = atan(7/9), B = atan(7), C = atan(7/4). Their sum is 180°. This approach also handles vertical sides, where a finite slope formula is unavailable.')])]
for p in PAGES:
 p.update(title='PLANE ANALYTIC GEOMETRY STRAIGHT LINE',visualStatus='Complete source family-of-lines and triangle-angle derivations with three native figures and checked branch selection',alternateVerification={'pdf':'Math Book for 12 class KPTBB.pdf','pdfPage':103,'side':'left' if p['page']==197 else 'right','reason':'All λ coefficients, signed inverse tangents and source vertices visually checked'})
EXAMPLES=[]
for n,q,steps,ans,p in [
('19','Find the family through 2x−3y+4 = 0 and 2x+y−1 = 0; select (a) a line parallel to slope −2/3 and (b) a line perpendicular to 4x+3y−1 = 0.',['Form L₁+λL₂ = (2+2λ)x+(−3+λ)y+(4−λ) = 0. The full pencil also includes L₂ itself.','For λ ≠ 3, its slope is −(2+2λ)/(−3+λ).','(a) Set this slope equal to −2/3. Cross-multiply to obtain 6+6λ = −6+2λ, hence λ = −3.','Substitute λ = −3: −4x−6y+7 = 0, equivalent to 4x+6y−7 = 0. Its slope is −2/3.','(b) The reference line has slope −4/3, so a perpendicular line has slope 3/4.','Setting −(2+2λ)/(−3+λ) = 3/4 gives −8−8λ = −9+3λ, hence λ = 1/11.','Substitute and multiply by 11: 24x−32y+43 = 0, whose slope is 3/4.','Solve the two original lines to get their intersection (−1/8,5/4). Substitution gives zero in both selected equations, independently checking that each belongs to the pencil.'],'Family (2x−3y+4)+λ(2x+y−1) = 0, plus L₂; (a) 4x+6y−7 = 0; (b) 24x−32y+43 = 0.',197),
('20','Find the interior angles of A(−2,−3), B(4,−1), C(2,3).',['At A, take rays AB = (6,2) and AC = (4,6). Their dot product is 36 and cross magnitude is 28.','Thus A = atan2(28,36) = atan(7/9) ≈ 37.874984°.','At B, take BA = (−6,−2) and BC = (−2,4). Their dot product is 4 and cross magnitude is 28.','Thus B = atan2(28,4) = atan(7) ≈ 81.869898°.','At C, take CA = (−4,−6) and CB = (2,−4). Their dot product is 16 and cross magnitude is 28.','Thus C = atan2(28,16) = atan(7/4) ≈ 60.255119°.','All three are positive and their sum is 180° (up to displayed rounding), so they are the interior angles.','The source’s negative principal inverse tangents are retained in the lesson but are not used as interior-angle answers. Using vertex rays avoids sign and supplementary-angle ambiguity.'],'A ≈ 37.874984°, B ≈ 81.869898°, C ≈ 60.255119°.',198)]:
 EXAMPLES.append({'num':n,'title':'Line Family' if n=='19' else 'Triangle Interior Angles','question':q,'steps':steps,'answer':ans,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':p,'jpg':'103_page_'+('1' if p==197 else '2')+'.jpg','verification':'Complete source question, coefficients and vertices checked'}],**({'sourceQuestionBlocks':[example_triangle()]} if n=='20' else {})})
